int n = 5;
int sum = 0;
for (int i = 1; i <= n; i++) {
    int num;
    scanf("%d", &num);
    if (num % 2 == 0) {
        sum += num;
    }
}

int n = 5;
int sum = 0;
int count = 0;
for (int i = 1; i <= n; i++) {
    int num;
    scanf("%d", &num);
    if (num % 2 != 0) {
        sum += num;
        count++;
    }
}
int avg = sum / count;

int sum = 0;
for (int i = 1; i <= n; i++) {
    sum += i;
}
int avg = sum / n;
printf("%d\n", avg);

int max;
int num;
scanf("%d", &max);
int i;
for (i = 2; i <= 5; i++) {
    scanf("%d", &num);
    if (num > max) {
        max = num;
    }
}
printf("%d %d\n", i, max);
